// JLS (Java Language Specification) opisuje SAM JEZYK Javy - skladnie, semantyke wyrazen,
// reguly typowania oraz model pamieci Javy (Java Memory Model). Przyklad tego, co reguluje
// JLS: dokladna kolejnosc wykonania operatorow w wyrazeniu 'a + b * c' (priorytet operatorow).
// JVMS (Java Virtual Machine Specification) opisuje MASZYNE WIRTUALNA - format pliku .class,
// zestaw instrukcji bajtkodu, zachowanie maszyny stosowej. Przyklad tego, co reguluje JVMS:
// dokladny format naglowka pliku .class (magic number 0xCAFEBABE, numer wersji bajtkodu).
// Obie sa dokumentami TEKSTOWYMI opisujacymi WYMAGANE zachowanie - kazdy moze napisac
// wlasna, zgodna implementacje kompilatora (dla JLS) lub JVM (dla JVMS).

static String describeJvmImplementation(String vmName) {
    String lower = vmName.toLowerCase();
    if (lower.contains("hotspot")) return "HotSpot - domyslna JVM z OpenJDK/Oracle JDK";
    if (lower.contains("openj9")) return "Eclipse OpenJ9 - szybki start, niskie zuzycie pamieci";
    if (lower.contains("substrate") || lower.contains("graal")) return "GraalVM - alternatywny JIT + mozliwosc AOT";
    return "Nieznana implementacja: " + vmName;
}

System.out.println(describeJvmImplementation("OpenJDK 64-Bit Server VM"));
System.out.println(describeJvmImplementation("Eclipse OpenJ9 VM"));
System.out.println(describeJvmImplementation("Substrate VM"));

record JvmInfo(String nazwa, String cecha, String zastosowanie) {}
JvmInfo[] jvms = {
    new JvmInfo("HotSpot", "JIT identyfikuje gorace metody", "domyslna JVM produkcyjna"),
    new JvmInfo("GraalVM", "wlasny JIT (Graal) + AOT Native Image", "blyskawiczny start, mikroserwisy"),
    new JvmInfo("Eclipse OpenJ9", "szybki start, niskie zuzycie pamieci", "kontenery/chmura")
};
for (JvmInfo j : jvms) {
    System.out.printf("%-16s | %-38s | %s%n", j.nazwa(), j.cecha(), j.zastosowanie());
}

Map<String, String> all = new TreeMap<>();
for (String key : System.getProperties().stringPropertyNames()) {
