all.forEach((k, v) -> { if (k.contains("vm")) System.out.println(k + " = " + v); });
System.out.println("=== Specyfikacja ===");
all.forEach((k, v) -> { if (k.contains("specification")) System.out.println(k + " = " + v); });
System.out.println("=== Vendor ===");
all.forEach((k, v) -> { if (k.contains("vendor")) System.out.println(k + " = " + v); });

static boolean meetsMinimumJavaVersion(int required) {
    return Runtime.version().feature() >= required;
}
for (int req : new int[]{8, 11, 17, 21, 25}) {
    System.out.println("Wymagane " + req + ": " + meetsMinimumJavaVersion(req));
}

String[] tokens = System.getProperty("java.vm.name").split("\\s+");
for (int i = 0; i < tokens.length; i++) {
    System.out.println((i + 1) + ". " + tokens[i]);
}

static String readPropertyOrDefault(String key, String def) {
    return System.getProperty(key, def);
}
System.out.println(readPropertyOrDefault("java.vm.name", "BRAK"));
System.out.println(readPropertyOrDefault("moj.wymyslony.klucz", "BRAK"));

String[] prefixes = {"java.", "os.", "user.", "sun."};
for (String prefix : prefixes) {
    long count = System.getProperties().stringPropertyNames().stream()
        .filter(k -> k.startsWith(prefix)).count();
    System.out.println(prefix + "* -> " + count + " wlasciwosci");
}

List<String> required = List.of("java.specification.version", "java.vm.name", "java.vendor");
for (String key : required) {
    String value = System.getProperty(key);
    boolean ok = value != null && !value.isBlank();
    System.out.println(key + ": " + (ok ? "OK (" + value + ")" : "BRAK"));
}

