static void compareVersions(String v1, String v2) {
    int major1 = Integer.parseInt(v1.split("\\.")[0]);
    int major2 = Integer.parseInt(v2.split("\\.")[0]);
    if (major1 > major2) System.out.println(v1 + " jest nowsza niz " + v2);
    else if (major2 > major1) System.out.println(v2 + " jest nowsza niz " + v1);
    else System.out.println(v1 + " i " + v2 + " maja ten sam major");
}
compareVersions("17.0.9", "21.0.2");

